&lt;h2 data-section-id=&quot;8mvev7&quot; data-start=&quot;1417&quot; data-end=&quot;1446&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Your Skills and Experience&lt;/span&gt;&lt;/h2&gt;
&lt;ul data-start=&quot;1447&quot; data-end=&quot;1994&quot;&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-section-id=&quot;g9rlsm&quot; data-start=&quot;1447&quot; data-end=&quot;1504&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;2+ years of index options volatility trading experience&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-section-id=&quot;1nbqgbq&quot; data-start=&quot;1505&quot; data-end=&quot;1573&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;BS, MS, or PhD, preferably in business, economics, or a STEM field&lt;/span&gt;&lt;/li&gt;
